#include "std_include.h"
#include "cuda_runtime.h"
#include "vertexQuadraticEnergy.h"
#include "vertexTrajectoryDatabase.h"
#include "twoValuesDatabase.h"
#include "analysisPackage.h"
#include "periodicBoundaries.h"
#include <filesystem>
#include <glob.h>
#include <cmath>
#include <cstdio>

// Generated by Cursor. 2026-09-14
// Isotropic S(q) of AVM cell centroids from vertex production trajectories.
// Physics: rho(K) = sum_n exp(i K · r_n), S(K) = |rho|^2 / N, then annular
// average on K = (i,j) 2 pi / L (same as structuralFeatures::computeStructureFactor).
// Per (p0, T): last nKeep log-spaced records of each idx, then mean S(q).
// Writes twoValuesDatabase (q, S) under productionRuns/structureFactor/.
// -s nKeep (default 10), -i/-j idx range (default 0..9), -k intKMax, -d dk.

static string findTrajectory(const string &dir, int N, double p0, double T, int idx)
    {
    char globpat[1024];
    snprintf(globpat, sizeof(globpat),
             "%sglassyDynamics_N%i_p%.4f_T%.8f_waitingTime*_idx%i.nc",
             dir.c_str(), N, p0, T, idx);
    glob_t g;
    g.gl_offs = 0;
    int rc = glob(globpat, 0, NULL, &g);
    string out;
    if (rc == 0 && g.gl_pathc > 0)
        out = g.gl_pathv[0];
    globfree(&g);
    return out;
    }

int main(int argc, char *argv[])
    {
    int numpts = 4096;
    int USE_GPU = -1;
    double T = 0.01;
    double p0 = 3.8;
    double intk = 2.0;
    double dk = 0.5;
    int nKeep = 10;
    int idxLo = 0;
    int idxHi = 9;

    int c;
    while ((c = getopt(argc, argv, "n:g:p:v:k:d:s:i:j:")) != -1)
        switch (c)
            {
            case 'n': numpts = atoi(optarg); break;
            case 'g': USE_GPU = atoi(optarg); break;
            case 'v': T = atof(optarg); break;
            case 'p': p0 = atof(optarg); break;
            case 'k': intk = atof(optarg); break;
            case 'd': dk = atof(optarg); break;
            case 's': nKeep = atoi(optarg); break;
            case 'i': idxLo = atoi(optarg); break;
            case 'j': idxHi = atoi(optarg); break;
            case '?':
                return 1;
            default:
                abort();
            };

    bool reproducible = true;
    bool initializeGPU = true;
    bool gpu = chooseGPU(USE_GPU);
    if (!gpu)
        initializeGPU = false;

    const char *scratchEnv = getenv("CELLGPU_SCRATCH");
    string scratch = scratchEnv ? scratchEnv : "/scratch/bbtm/cli6/glassyDynamics/data";

    char loadfolder[512];
    char savefolder[512];
    char saveDataName[512];
    snprintf(loadfolder, sizeof(loadfolder), "%s/N%i/vertex/productionRuns/p%.3f/",
             scratch.c_str(), numpts, p0);
    snprintf(savefolder, sizeof(savefolder), "%s/N%i/vertex/productionRuns/structureFactor/",
             scratch.c_str(), numpts);
    snprintf(saveDataName, sizeof(saveDataName), "%ssq_N%i_p%.4f_T%.8f.nc",
             savefolder, numpts, p0, T);

    namespace fs = std::filesystem;
    fs::create_directories(savefolder);

    cout << "p0 = " << p0 << " T = " << T << " nKeep = " << nKeep
         << " idx = " << idxLo << ".." << idxHi
         << " intKMax = " << intk << " dk = " << dk << endl;
    cout << "load dir " << loadfolder << endl;
    cout << "write " << saveDataName << endl;

    int Nvert = 2 * numpts;
    shared_ptr<VertexQuadraticEnergy> avm =
        make_shared<VertexQuadraticEnergy>(numpts, 1.0, p0, reproducible, false, initializeGPU);
    if (!initializeGPU)
        avm->setCPU();
    avm->setCellPreferencesUniform(1.0, p0);

    structuralFeatures strucFeat(avm->Box);
    vector<double> qGrid;
    vector<double> sSum;
    int nUsed = 0;
    int nMissing = 0;
    int nShort = 0;

    for (int idx = idxLo; idx <= idxHi; ++idx)
        {
        string loaddataname = findTrajectory(string(loadfolder), numpts, p0, T, idx);
        if (loaddataname.empty())
            {
            cout << "missing idx=" << idx << endl;
            nMissing += 1;
            continue;
            }
        cout << "reading " << loaddataname << endl;
        vertexTrajectoryDatabase traj(Nvert, loaddataname, NcFile::ReadOnly);
        int nrec = traj.GetNumRecs();
        if (nrec < nKeep)
            {
            cout << "records = " << nrec << " < " << nKeep << "; skip idx=" << idx << endl;
            nShort += 1;
            continue;
            }
        int rec0 = nrec - nKeep;
        for (int rec = rec0; rec < nrec; ++rec)
            {
            traj.readState(avm, rec, true);
            strucFeat.setBox(avm->Box);
            vector<double2> posdat(numpts);
            ArrayHandle<double2> h_p(avm->cellPositions, access_location::host, access_mode::read);
            for (int ii = 0; ii < numpts; ++ii)
                posdat[ii] = h_p.data[ii];
            vector<double2> SofK;
            strucFeat.computeStructureFactor(posdat, SofK, intk, dk);
            if (qGrid.empty())
                {
                qGrid.resize(SofK.size());
                sSum.assign(SofK.size(), 0.0);
                for (size_t iq = 0; iq < SofK.size(); ++iq)
                    qGrid[iq] = SofK[iq].x;
                }
            else if (SofK.size() != qGrid.size())
                {
                cout << "q-grid size mismatch at idx=" << idx << " rec=" << rec << "; skip frame" << endl;
                continue;
                }
            for (size_t iq = 0; iq < SofK.size(); ++iq)
                sSum[iq] += SofK[iq].y;
            nUsed += 1;
            }
        }

    cout << "n_used = " << nUsed << " n_missing = " << nMissing << " n_short = " << nShort << endl;
    if (nUsed == 0 || qGrid.empty())
        {
        cout << "no S(q) accumulated; abort" << endl;
        return 1;
        }

    shared_ptr<twoValuesDatabase> out = make_shared<twoValuesDatabase>(saveDataName, NcFile::Replace);
    for (size_t iq = 0; iq < qGrid.size(); ++iq)
        out->writeValues(qGrid[iq], sSum[iq] / (double)nUsed);

    if (initializeGPU)
        cudaDeviceReset();
    return 0;
    }
